Here's Orb Runner, a single self-contained HTML file. Collect orbs (gold orbs are worth 5), dodge the red hazards, and reach 50 points to win. Hazards multiply and speed up as time passes.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Orb Runner</title>
<style>
  html, body { margin: 0; height: 100%; background: #03040a; overflow: hidden; }
  body { display: flex; align-items: center; justify-content: center; }
  canvas {
    display: block;
    background: #0a0c1a;
    outline: none;
    width: min(100vw, calc(100vh * 4 / 3));
    height: min(100vh, calc(100vw * 3 / 4));
    box-shadow: 0 0 60px rgba(60, 120, 255, 0.25);
    cursor: crosshair;
    touch-action: none;
    user-select: none;
  }
</style>
</head>
<body>
<canvas id="c" width="800" height="600" tabindex="0"></canvas>
<script>
(() => {
  const canvas = document.getElementById('c');
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;

  // ---- Constants ----
  const WIN_SCORE = 50;
  const PLAYER_R = 12;        // visual radius
  const PLAYER_HIT = 9;       // collision radius for player
  const HAZARD_HIT = 13;      // collision radius for hazards
  const PLAYER_SPEED = 330;   // px/s

  // ---- Test hook (keep in sync) ----
  window.gameState = { score: 0, state: 'menu' };

  // ---- Game state ----
  let state = 'menu';         // 'menu' | 'playing' | 'over' | 'won'
  let score = 0;
  let best = loadBest();
  let elapsed = 0;
  let paused = false;
  let cooldown = 0;           // seconds before restart is accepted
  let shake = 0;

  let player, orbs, hazards, particles, stars;
  const keys = { left: false, right: false, up: false, down: false };
  const mouse = { x: W / 2, y: H / 2, active: false };

  // ---- Utilities ----
  const randRange = (a, b) => a + Math.random() * (b - a);
  const dist = (ax, ay, bx, by) => Math.hypot(ax - bx, ay - by);
  const dangerLevel = () => 1 + Math.floor(elapsed / 12);
  const fmtTime = s => {
    const m = Math.floor(s / 60), sec = Math.floor(s % 60);
    return `${m}:${sec < 10 ? '0' : ''}${sec}`;
  };
  function loadBest() {
    try { return parseInt(localStorage.getItem('orbRunnerBest') || '0', 10) || 0; } catch (e) { return 0; }
  }
  function saveBest() {
    try { localStorage.setItem('orbRunnerBest', String(best)); } catch (e) {}
  }
  function sync() {
    window.gameState.score = score;
    window.gameState.state = state;
  }

  // ---- Sound (generated with WebAudio, no files) ----
  let audioCtx = null;
  function ensureAudio() {
    if (!audioCtx) {
      try { audioCtx = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { audioCtx = null; }
    }
    if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
    return audioCtx;
  }
  function tone(freq, dur = 0.12, type = 'sine', vol = 0.15, slideTo = null, delay = 0) {
    const ac = ensureAudio();
    if (!ac) return;
    const t0 = ac.currentTime + delay;
    const o = ac.createOscillator();
    const g = ac.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t0);
    if (slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, t0 + dur);
    g.gain.setValueAtTime(vol, t0);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    o.connect(g);
    g.connect(ac.destination);
    o.start(t0);
    o.stop(t0 + dur + 0.02);
  }
  const sfx = {
    collect: () => tone(600 + Math.random() * 250, 0.1, 'sine', 0.12, 1100),
    gold: () => { tone(880, 0.1, 'triangle', 0.15); tone(1320, 0.15, 'triangle', 0.12, null, 0.08); },
    hit: () => tone(220, 0.5, 'sawtooth', 0.18, 40),
    start: () => [523, 659, 784, 1047].forEach((f, i) => tone(f, 0.12, 'square', 0.07, null, i * 0.07)),
    win: () => [523, 659, 784, 1047, 1319].forEach((f, i) => tone(f, 0.25, 'triangle', 0.13, null, i * 0.1))
  };

  // ---- Spawning ----
  function spawnOrb() {
    let x, y, tries = 0;
    do {
      x = randRange(30, W - 30);
      y = randRange(30, H - 30);
      tries++;
    } while (dist(x, y, player.x, player.y) < 90 && tries < 20);
    const gold = Math.random() < 0.12;
    orbs.push({ x, y, r: gold ? 9 : 7, gold, life: 7, age: 0, phase: Math.random() * Math.PI * 2 });
  }

  function spawnHazard() {
    let x, y, tries = 0;
    do {
      x = randRange(20, W - 20);
      y = randRange(20, H - 20);
      tries++;
    } while (dist(x, y, player.x, player.y) < 180 && tries < 30);
    const seekers = hazards.filter(h => h.type === 'seeker').length;
    const type = (elapsed > 25 && seekers < 2 && Math.random() < 0.3) ? 'seeker' : 'bouncer';
    hazards.push({
      type, x, y, r: 14,
      a: Math.random() * Math.PI * 2,
      spin: Math.random() * Math.PI * 2,
      dir: Math.random() < 0.5 ? -1 : 1
    });
  }

  function burst(x, y, rgb, n, speed) {
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2;
      const s = speed * (0.3 + Math.random() * 0.7);
      const life = 0.5 + Math.random() * 0.5;
      particles.push({ x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, life, max: life, rgb });
    }
  }

  // ---- Reset / state changes ----
  function reset() {
    score = 0;
    elapsed = 0;
    shake = 0;
    paused = false;
    player = { x: W / 2, y: H / 2, trail: [] };
    orbs = [];
    hazards = [];
    particles = [];
    for (let i = 0; i < 4; i++) spawnOrb();
  }

  function startGame() {
    ensureAudio();
    reset();
    state = 'playing';
    sfx.start();
    sync();
  }

  function die() {
    state = 'over';
    best = Math.max(best, score);
    saveBest();
    shake = 1;
    burst(player.x, player.y, '255,80,120', 40, 320);
    sfx.hit();
    cooldown = 0.7;
    sync();
  }

  function win() {
    state = 'won';
    best = Math.max(best, score);
    saveBest();
    burst(player.x, player.y, '255,210,60', 60, 380);
    sfx.win();
    cooldown = 0.7;
    sync();
  }

  function togglePause() {
    if (state === 'playing') paused = !paused;
  }

  function onPress() {
    if (state === 'menu') startGame();
    else if ((state === 'over' || state === 'won') && cooldown <= 0) startGame();
  }

  // ---- Update ----
  function update(dt) {
    // Player movement: keyboard overrides mouse; mouse follows cursor when no keys held
    let dx = 0, dy = 0;
    if (keys.left) dx--;
    if (keys.right) dx++;
    if (keys.up) dy--;
    if (keys.down) dy++;
    if (dx || dy) {
      const l = Math.hypot(dx, dy);
      player.x += dx / l * PLAYER_SPEED * dt;
      player.y += dy / l * PLAYER_SPEED * dt;
    } else if (mouse.active) {
      const ddx = mouse.x - player.x, ddy = mouse.y - player.y, d = Math.hypot(ddx, ddy);
      if (d > 1) {
        const step = Math.min(d, PLAYER_SPEED * 1.3 * dt);
        player.x += ddx / d * step;
        player.y += ddy / d * step;
      }
    }
    player.x = Math.max(PLAYER_R, Math.min(W - PLAYER_R, player.x));
    player.y = Math.max(PLAYER_R, Math.min(H - PLAYER_R, player.y));

    player.trail.push({ x: player.x, y: player.y, life: 0.35 });
    for (const t of player.trail) t.life -= dt;
    player.trail = player.trail.filter(t => t.life > 0);

    elapsed += dt;
    shake = Math.max(0, shake - dt * 2);

    // Spawn: hazard count grows with time; orbs are kept topped up
    const maxHazards = Math.min(3 + Math.floor(elapsed / 12), 12);
    if (hazards.length < maxHazards && Math.random() < dt * 1.2) spawnHazard();
    if (orbs.length < 5 && Math.random() < dt * 1.8) spawnOrb();

    // Orbs age out
    for (const o of orbs) o.age += dt;
    orbs = orbs.filter(o => o.age < o.life);

    // Hazards move; speed ramps with time
    const bounceSpeed = Math.min(70 + elapsed * 3, 280);
    const seekSpeed = Math.min(40 + elapsed * 1.2, 170);
    for (const h of hazards) {
      h.spin += dt * (h.type === 'seeker' ? 3 : 1.5) * h.dir;
      if (h.type === 'bouncer') {
        h.x += Math.cos(h.a) * bounceSpeed * dt;
        h.y += Math.sin(h.a) * bounceSpeed * dt;
        if (h.x < h.r) { h.x = h.r; h.a = Math.PI - h.a; }
        if (h.x > W - h.r) { h.x = W - h.r; h.a = Math.PI - h.a; }
        if (h.y < h.r) { h.y = h.r; h.a = -h.a; }
        if (h.y > H - h.r) { h.y = H - h.r; h.a = -h.a; }
      } else {
        const ddx = player.x - h.x, ddy = player.y - h.y;
        const d = Math.hypot(ddx, ddy) || 1;
        h.x += ddx / d * seekSpeed * dt;
        h.y += ddy / d * seekSpeed * dt;
      }
    }

    // Orb pickups
    let gotGold = false, gotOrb = false;
    for (let i = orbs.length - 1; i >= 0; i--) {
      const o = orbs[i];
      if (dist(o.x, o.y, player.x, player.y) < o.r + PLAYER_R) {
        score += o.gold ? 5 : 1;
        if (o.gold) gotGold = true; else gotOrb = true;
        burst(o.x, o.y, o.gold ? '255,210,60' : '90,240,255', o.gold ? 24 : 12, 160);
        orbs.splice(i, 1);
      }
    }
    if (gotGold) sfx.gold();
    else if (gotOrb) sfx.collect();

    // Win check
    if (score >= WIN_SCORE) { win(); return; }

    // Hazard collisions
    for (const h of hazards) {
      if (dist(h.x, h.y, player.x, player.y) < HAZARD_HIT + PLAYER_HIT) { die(); return; }
    }
  }

  function updateParticles(dt) {
    for (const p of particles) {
      p.life -= dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      const drag = Math.pow(0.1, dt);
      p.vx *= drag;
      p.vy *= drag;
    }
    particles = particles.filter(p => p.life > 0);
  }

  function updateStars(dt) {
    const boost = state === 'playing' ? Math.min(elapsed / 60, 1.5) : 0;
    for (const s of stars) {
      s.y += s.v * (1 + boost) * dt;
      if (s.y > H) { s.y = 0; s.x = Math.random() * W; }
    }
  }

  // ---- Rendering ----
  function drawGrid() {
    ctx.strokeStyle = 'rgba(80,120,255,0.06)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let x = 0; x <= W; x += 40) { ctx.moveTo(x + 0.5, 0); ctx.lineTo(x + 0.5, H); }
    for (let y = 0; y <= H; y += 40) { ctx.moveTo(0, y + 0.5); ctx.lineTo(W, y + 0.5); }
    ctx.stroke();
  }

  function drawStars() {
    for (const s of stars) {
      ctx.fillStyle = `rgba(200,220,255,${0.25 + s.s * 0.35})`;
      ctx.fillRect(s.x, s.y, s.s, s.s);
    }
  }

  function drawTrail() {
    for (const t of player.trail) {
      const k = Math.max(0, t.life / 0.35);
      ctx.globalAlpha = k * 0.4;
      ctx.fillStyle = '#8ff';
      ctx.beginPath();
      ctx.arc(t.x, t.y, PLAYER_R * k * 0.8, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  function drawOrbs() {
    for (const o of orbs) {
      const fade = Math.min(1, (o.life - o.age), o.age / 0.3);
      const pulse = 1 + Math.sin(o.age * 4 + o.phase) * 0.15;
      const r = o.r * pulse;
      const col = o.gold ? '255,210,60' : '90,240,255';
      ctx.save();
      ctx.globalAlpha = fade;
      const g = ctx.createRadialGradient(o.x, o.y, 0, o.x, o.y, r * 3);
      g.addColorStop(0, `rgba(${col},0.55)`);
      g.addColorStop(1, `rgba(${col},0)`);
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.arc(o.x, o.y, r * 3, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = `rgb(${col})`;
      ctx.beginPath(); ctx.arc(o.x, o.y, r, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#fff';
      ctx.beginPath(); ctx.arc(o.x - r * 0.3, o.y - r * 0.3, r * 0.3, 0, Math.PI * 2); ctx.fill();
      ctx.restore();
    }
  }

  function drawHazards() {
    for (const h of hazards) {
      const color = h.type === 'seeker' ? '#ff9a3c' : '#ff2d6f';
      ctx.save();
      ctx.translate(h.x, h.y);
      ctx.rotate(h.spin);
      ctx.shadowColor = color;
      ctx.shadowBlur = 18;
      ctx.fillStyle = color;
      ctx.beginPath();
      const pts = 8;
      for (let i = 0; i < pts * 2; i++) {
        const rr = i % 2 === 0 ? h.r * 1.5 : h.r * 0.55;
        const a = i * Math.PI / pts;
        ctx.lineTo(Math.cos(a) * rr, Math.sin(a) * rr);
      }
      ctx.closePath();
      ctx.fill();
      ctx.shadowBlur = 0;
      ctx.fillStyle = 'rgba(20,0,10,0.6)';
      ctx.beginPath(); ctx.arc(0, 0, h.r * 0.45, 0, Math.PI * 2); ctx.fill();
      ctx.restore();
    }
  }

  function drawPlayer() {
    ctx.save();
    ctx.shadowColor = '#8ff';
    ctx.shadowBlur = 24;
    ctx.fillStyle = '#e8ffff';
    ctx.beginPath();
    ctx.arc(player.x, player.y, PLAYER_R, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  function drawParticles() {
    for (const p of particles) {
      const a = Math.max(0, p.life / p.max);
      ctx.fillStyle = `rgba(${p.rgb},${a})`;
      ctx.fillRect(p.x - 1.5, p.y - 1.5, 3, 3);
    }
  }

  function text(t, x, y, size = 18, color = '#cfe') {
    ctx.save();
    ctx.font = `${size}px system-ui, sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = color;
    ctx.fillText(t, x, y);
    ctx.restore();
  }

  function glowText(t, x, y, size, color) {
    ctx.save();
    ctx.font = `bold ${size}px system-ui, sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.shadowColor = color;
    ctx.shadowBlur = 25;
    ctx.fillStyle = color;
    ctx.fillText(t, x, y);
    ctx.restore();
  }

  function dim(alpha = 0.72) {
    ctx.fillStyle = `rgba(5,6,13,${alpha})`;
    ctx.fillRect(0, 0, W, H);
  }

  function drawHUD() {
    ctx.save();
    ctx.textBaseline = 'top';
    ctx.font = 'bold 20px system-ui, sans-serif';
    ctx.fillStyle = '#e8ffff';
    ctx.textAlign = 'left';
    ctx.fillText(`SCORE ${score}`, 16, 14);
    ctx.textAlign = 'center';
    ctx.fillText(`TIME ${fmtTime(elapsed)}`, W / 2, 14);
    ctx.textAlign = 'right';
    ctx.fillText(`BEST ${Math.max(best, score)}`, W - 16, 14);

    ctx.font = '13px system-ui, sans-serif';
    ctx.fillStyle = '#ff7aa0';
    ctx.textAlign = 'left';
    ctx.fillText(`DANGER ${dangerLevel()}`, 16, 42);
    ctx.fillStyle = 'rgba(255,255,255,0.7)';
    ctx.textAlign = 'right';
    ctx.fillText(`GOAL ${WIN_SCORE}`, W - 16, 42);

    const p = Math.min(score / WIN_SCORE, 1);
    ctx.fillStyle = 'rgba(255,255,255,0.12)';
    ctx.fillRect(16, H - 16, W - 32, 6);
    ctx.fillStyle = '#ffd23f';
    ctx.fillRect(16, H - 16, (W - 32) * p, 6);
    ctx.restore();
  }

  function drawMenu() {
    dim(0.6);
    glowText('ORB RUNNER', W / 2, 120, 64, '#5ff0ff');
    text('Collect the glowing orbs to score. Gold orbs are worth 5.', W / 2, 200, 17, '#cfe');
    text('Dodge the red hazards. They multiply and speed up over time.', W / 2, 228, 17, '#cfe');
    text(`Reach ${WIN_SCORE} points to win.`, W / 2, 256, 17, '#ffd23f');

    text('CONTROLS', W / 2, 320, 16, '#8ff');
    text('Move: Arrow keys / WASD, or move the mouse', W / 2, 350, 16);
    text('Pause: P', W / 2, 378, 16);
    text('Start / restart: Enter, Space, or click', W / 2, 406, 16);

    const pulse = 0.6 + Math.sin(performance.now() / 300) * 0.4;
    ctx.save();
    ctx.globalAlpha = pulse;
    glowText('Press ENTER / SPACE or CLICK to start', W / 2, 500, 22, '#ffffff');
    ctx.restore();
  }

  function drawOver() {
    dim();
    glowText('GAME OVER', W / 2, 200, 60, '#ff2d6f');
    text(`Score: ${score}`, W / 2, 285, 28, '#e8ffff');
    text(`Best: ${Math.max(best, score)}   Time: ${fmtTime(elapsed)}`, W / 2, 325, 18, '#cfe');
    if (cooldown <= 0) {
      const pulse = 0.6 + Math.sin(performance.now() / 300) * 0.4;
      ctx.save();
      ctx.globalAlpha = pulse;
      text('Press ENTER / SPACE or CLICK to try again', W / 2, 410, 20, '#ffffff');
      ctx.restore();
    }
  }

  function drawWon() {
    dim();
    glowText('YOU WIN!', W / 2, 200, 60, '#ffd23f');
    text(`Reached ${WIN_SCORE} points in ${fmtTime(elapsed)}`, W / 2, 285, 24, '#e8ffff');
    text(`Best: ${Math.max(best, score)}`, W / 2, 325, 18, '#cfe');
    if (cooldown <= 0) {
      const pulse = 0.6 + Math.sin(performance.now() / 300) * 0.4;
      ctx.save();
      ctx.globalAlpha = pulse;
      text('Press ENTER / SPACE or CLICK to play again', W / 2, 410, 20, '#ffffff');
      ctx.restore();
    }
  }

  function drawPaused() {
    dim(0.5);
    glowText('PAUSED', W / 2, H / 2 - 10, 48, '#5ff0ff');
    text('Press P to resume', W / 2, H / 2 + 40, 18, '#cfe');
  }

  function render() {
    ctx.save();
    if (shake > 0) {
      ctx.translate(randRange(-1, 1) * shake * 10, randRange(-1, 1) * shake * 10);
    }
    ctx.fillStyle = '#0a0c1a';
    ctx.fillRect(-30, -30, W + 60, H + 60);
    drawGrid();
    drawStars();
    if (state !== 'menu') {
      drawOrbs();
      drawHazards();
      drawTrail();
      drawPlayer();
      drawParticles();
    }
    ctx.restore();

    if (state === 'playing') {
      drawHUD();
      if (paused) drawPaused();
    } else if (state === 'menu') {
      drawMenu();
    } else if (state === 'over') {
      drawOver();
    } else if (state === 'won') {
      drawWon();
    }
  }

  // ---- Input ----
  const KEYMAP = {
    ArrowLeft: 'left', KeyA: 'left',
    ArrowRight: 'right', KeyD: 'right',
    ArrowUp: 'up', KeyW: 'up',
    ArrowDown: 'down', KeyS: 'down'
  };

  window.addEventListener('keydown', e => {
    const k = KEYMAP[e.code];
    if (k) { keys[k] = true; e.preventDefault(); }
    if (e.code === 'Space' || e.code === 'Enter') {
      e.preventDefault();
      if (!e.repeat) onPress();
    }
    if (e.code === 'KeyP' && !e.repeat) togglePause();
  });

  window.addEventListener('keyup', e => {
    const k = KEYMAP[e.code];
    if (k) keys[k] = false;
  });

  window.addEventListener('blur', () => {
    for (const k in keys) keys[k] = false;
  });

  function toCanvas(p) {
    const r = canvas.getBoundingClientRect();
    return { x: (p.clientX - r.left) * W / r.width, y: (p.clientY - r.top) * H / r.height };
  }

  canvas.addEventListener('mousemove', e => {
    const p = toCanvas(e);
    mouse.x = p.x;
    mouse.y = p.y;
    mouse.active = true;
  });
  canvas.addEventListener('mouseleave', () => { mouse.active = false; });
  canvas.addEventListener('mousedown', () => {
    canvas.focus();
    onPress();
  });

  canvas.addEventListener('touchstart', e => {
    e.preventDefault();
    const p = toCanvas(e.touches[0]);
    mouse.x = p.x; mouse.y = p.y; mouse.active = true;
    onPress();
  }, { passive: false });
  canvas.addEventListener('touchmove', e => {
    e.preventDefault();
    const p = toCanvas(e.touches[0]);
    mouse.x = p.x; mouse.y = p.y; mouse.active = true;
  }, { passive: false });

  // ---- Main loop ----
  stars = Array.from({ length: 70 }, () => ({
    x: Math.random() * W,
    y: Math.random() * H,
    s: 0.5 + Math.random() * 1.5,
    v: 8 + Math.random() * 25
  }));
  player = { x: W / 2, y: H / 2, trail: [] };
  orbs = [];
  hazards = [];
  particles = [];

  let lastTime = performance.now();
  function frame(now) {
    const dt = Math.min((now - lastTime) / 1000, 0.05);
    lastTime = now;

    if (state === 'playing' && !paused) update(dt);
    if (state === 'over' || state === 'won') cooldown -= dt;
    updateParticles(dt);
    updateStars(dt);

    render();
    sync();
    requestAnimationFrame(frame);
  }
  sync();
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
